contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry exercising addNodeDelegatorContractToQueue
    // params: array of addresses to add and a delta to possibly update maxNodeDelegatorCount beforehand
    function run(address[] calldata nodeDelegators, uint256 maybeNewMax) public payable {
        // record initial length
        uint256 beforeLen = c.getNodeDelegatorQueue().length;
        // optionally increase maxNodeDelegatorCount to a large value to allow additions
        // we must call updateMaxNodeDelegatorCount only through a top-level statement
        // but updateMaxNodeDelegatorCount is restricted to onlyLRTAdmin; this contract is the deployer and may not be admin
        // so we skip calling it to avoid relying on roles. Instead we observe behavior without changing roles.

        // perform the call and capture whether it reverted
        bool reverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;

        // Count how many inputs are non-zero (since zero address causes revert in UtilLib.checkNonZeroAddress())
        uint256 nonZeroInputs = 0;
        for (uint256 i = 0; i < nodeDelegators.length; ) {
            if (nodeDelegators[i] != address(0)) {
                unchecked { nonZeroInputs++; }
            }
            unchecked { ++i; }
        }

        // The general rule:
        // If the call reverted, the queue length must be unchanged (no partial pushes).
        // If the call did not revert, the queue length must have increased exactly by the number
        // of provided addresses (all non-zero) because the function pushes every address and only
        // reverts on zero address or when resulting length would exceed maxNodeDelegatorCount.
        // We express this by: if reverted -> afterLen == beforeLen; else -> afterLen == beforeLen + nonZeroInputs
        assert(reverted ? (afterLen == beforeLen) : (afterLen == beforeLen + nonZeroInputs));
    }

    // no special receive logic needed
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry: try adding one address to the nodeDelegatorQueue
    function run(address nodeDelegator) public payable {
        // require the input to be non-zero so the only reason for revert (from input) is exceeding max count or role checks
        require(nodeDelegator != address(0));

        uint256 beforeLen = c.getNodeDelegatorQueue().length;

        bool reverted;
        try c.addNodeDelegatorContractToQueue(new address[](1)) {
            // this branch won't be used because we pass non-empty array below differently; keep to satisfy try syntax
            reverted = false;
        } catch {
            reverted = true;
        }

        // Actually perform the real state-changing call as a top-level statement and capture revert
        bool realReverted;
        address[] memory arr = new address[](1);
        arr[0] = nodeDelegator;
        try c.addNodeDelegatorContractToQueue(arr) {
            realReverted = false;
        } catch {
            realReverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;

        // If the call reverted then length must be unchanged; otherwise length increases by exactly 1
        assert(realReverted ? (afterLen == beforeLen) : (afterLen == beforeLen + 1));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry: check that getTotalAssetDeposits equals the sum of components returned by getAssetDistributionData
    function run(address asset) public payable {
        // require non-zero asset so only supported-assets modifier can determine behavior (avoid zero-address corner)
        require(asset != address(0));

        // Try to call getAssetDistributionData; it will revert if asset is not supported. We only assert when it does not revert.
        bool reverted;
        uint256 a;
        uint256 b;
        uint256 d;
        try c.getAssetDistributionData(asset) returns (uint256 assetLyingInDepositPool, uint256 assetLyingInNDCs, uint256 assetStakedInEigenLayer) {
            reverted = false;
            a = assetLyingInDepositPool;
            b = assetLyingInNDCs;
            d = assetStakedInEigenLayer;
        } catch {
            reverted = true;
        }

        // If the call reverted (asset not supported), we cannot observe components; in that case require revert happened.
        if (reverted) {
            assert(reverted);
            return;
        }

        // Otherwise, read the aggregate via getTotalAssetDeposits and assert equality with the sum of the three components
        uint256 total = c.getTotalAssetDeposits(asset);

        assert(total == (a + b + d));
    }

    receive() external payable {}
}

